void MissionPlanner::on_set_waypoint_route(
  const SetWaypointRoute::Request::SharedPtr req, const SetWaypointRoute::Response::SharedPtr res)
{
  using ResponseCode = autoware_adapi_v1_msgs::srv::SetRoutePoints::Response;
  const auto is_reroute = state_.state == RouteState::SET;

  if (state_.state != RouteState::UNSET && state_.state != RouteState::SET) {
    throw service_utils::ServiceException(
      ResponseCode::ERROR_INVALID_STATE,
      fmt::format(
        "The waypoint route cannot be set in the current state: {}",
        route_state_to_string(state_.state)));
  }
  if (!is_mission_planner_ready_) {
    throw service_utils::ServiceException(
      ResponseCode::ERROR_PLANNER_UNREADY, "The mission planner is not ready.");
  }
  if (is_reroute && !operation_mode_state_) {
    throw service_utils::ServiceException(
      ResponseCode::ERROR_PLANNER_UNREADY, "Operation mode state is not received.");
  }

  const bool is_autonomous_driving =
    operation_mode_state_ ? operation_mode_state_->mode == OperationModeState::AUTONOMOUS &&
                              operation_mode_state_->is_autoware_control_enabled
                          : false;

  if (is_reroute && is_autonomous_driving) {
    const auto reroute_availability = sub_reroute_availability_.take_data();
    if (!reroute_availability || !reroute_availability->availability) {
      throw service_utils::ServiceException(
        ResponseCode::ERROR_INVALID_STATE,
        "Cannot reroute as the planner is not in lane following.");
    }
  }

  change_state(is_reroute ? RouteState::REROUTING : RouteState::ROUTING);
  const auto route = create_route(*req);

  if (route.segments.empty()) {
    cancel_route();
    change_state(is_reroute ? RouteState::SET : RouteState::UNSET);
    throw service_utils::ServiceException(
      ResponseCode::ERROR_PLANNER_FAILED, "The planned route is empty.");
  }

  if (is_reroute && is_autonomous_driving && !check_reroute_safety(*current_route_, route)) {
    cancel_route();
    change_state(RouteState::SET);
    throw service_utils::ServiceException(
      ResponseCode::ERROR_REROUTE_FAILED, "New route is not safe. Reroute failed.");
  }

  original_route_ = std::nullopt;

  change_route(route);
  change_state(RouteState::SET);
  res->status.success = true;

  print_pose_log("set_waypoint_route", odometry_->pose.pose, req->goal_pose);
}

void MissionPlanner::change_state(RouteState::_state_type state)
{
  state_.stamp = now();
  state_.state = state;
  pub_state_->publish(state_);
}

LaneletRoute MissionPlanner::create_route(const PoseWithUuidStamped & msg)
{
  const auto & header = msg.header;
  const auto & goal_pose = msg.pose;
  const auto & uuid = msg.uuid;
  const auto & allow_goal_modification = current_route_->allow_modification;

  // NOTE: Reroute by modifed goal is assumed to be a slight modification near the goal lane.
  //       It is assumed that ego and goal are on the extension of the current route at least.
  //       Therefore, the start pose is the start pose of the current route if it exists.
  //       This prevents the route from becoming shorter due to reroute.
  //       Also, use start pose and waypoints that are on the preferred lanelet of the current route
  //       as much as possible.
  //       For this process, refer to RouteHandler::planPathLaneletsBetweenCheckpoints() or
  //       https://github.com/autowarefoundation/autoware_universe/pull/8238 too.
  const auto & start_pose = current_route_ ? current_route_->start_pose : odometry_->pose.pose;
  std::vector<Pose> waypoints{};
  if (current_route_) {
    waypoints.push_back(odometry_->pose.pose);
  }

  return create_route(header, waypoints, start_pose, goal_pose, uuid, allow_goal_modification);
}

LaneletRoute MissionPlanner::create_route(
  const Header & header, const std::vector<Pose> & waypoints, const Pose & start_pose,
  const Pose & goal_pose, const UUID & uuid, const bool allow_goal_modification)
{
  PlannerPlugin::RoutePoints points;
  points.push_back(start_pose);
  for (const auto & waypoint : waypoints) {
    points.push_back(transform_pose(waypoint, header));
  }
  points.push_back(transform_pose(goal_pose, header));

  LaneletRoute route = planner_->plan(points);
  route.header.stamp = header.stamp;
  route.header.frame_id = map_frame_;
  route.uuid = uuid;
  route.allow_modification = allow_goal_modification;
  return route;
}

PlannerPlugin::LaneletRoute DefaultPlanner::plan(const RoutePoints & points)
{
  const auto logger = node_->get_logger();

  std::stringstream log_ss;
  for (const auto & point : points) {
    log_ss << "x: " << point.position.x << " "
           << "y: " << point.position.y << std::endl;
  }
  RCLCPP_DEBUG_STREAM(
    logger, "start planning route with check points: " << std::endl
                                                       << log_ss.str());

  LaneletRoute route_msg;
  RouteSections route_sections;

  lanelet::ConstLanelets all_route_lanelets;
  for (std::size_t i = 1; i < points.size(); i++) {
    const auto start_check_point = points.at(i - 1);
    const auto goal_check_point = points.at(i);

    lanelet::ConstLanelets path_lanelets;
    if (!route_handler_.planPathLaneletsBetweenCheckpoints(
          start_check_point, goal_check_point, &path_lanelets, param_.consider_no_drivable_lanes)) {
      RCLCPP_WARN(logger, "Failed to plan route.");
      return route_msg;
    }

    for (const auto & lane : path_lanelets) {
      if (!all_route_lanelets.empty() && lane.id() == all_route_lanelets.back().id()) continue;
      all_route_lanelets.push_back(lane);
    }
  }
  route_handler_.setRouteLanelets(all_route_lanelets);
  route_sections = route_handler_.createMapSegments(all_route_lanelets);

  auto goal_pose = points.back();
  if (param_.enable_correct_goal_pose) {
    goal_pose = get_closest_centerline_pose(
      lanelet::utils::query::laneletLayer(route_handler_.getLaneletMapPtr()), goal_pose,
      vehicle_info_);
  }

  if (!is_goal_valid(goal_pose)) {
    RCLCPP_WARN(logger, "Goal is not valid! Please check position and angle of goal_pose");
    return route_msg;
  }

  if (route_handler::RouteHandler::isRouteLooped(route_sections)) {
    RCLCPP_WARN(logger, "Loop detected within route!");
    return route_msg;
  }

  const auto refined_goal = refine_goal_height(goal_pose, route_sections);
  RCLCPP_DEBUG(logger, "Goal Pose Z : %lf", refined_goal.position.z);

  // The header is assigned by mission planner.
  route_msg.start_pose = points.front();
  route_msg.goal_pose = refined_goal;
  route_msg.segments = route_sections;
  return route_msg;
}

bool RouteHandler::planPathLaneletsBetweenCheckpoints(
  const Pose & start_checkpoint, const Pose & goal_checkpoint,
  lanelet::ConstLanelets * path_lanelets, const bool consider_no_drivable_lanes) const
{
  // Find lanelets for start point. First, find all lanelets containing the start point to
  // calculate all possible route later. It fails when the point is not located on any road
  // lanelet (e.g. the start point is located out of any lanelets or road_shoulder lanelet which
  // is not contained in road lanelet). In that case, find the closest lanelet instead (within
  // some maximum range).
  constexpr auto max_search_range = 20.0;
  auto start_lanelets = getRoadLaneletsAtPose(start_checkpoint);
  lanelet::ConstLanelet start_lanelet;
  if (start_lanelets.empty()) {
    const lanelet::BasicPoint2d p(start_checkpoint.position.x, start_checkpoint.position.y);
    const lanelet::BoundingBox2d bbox(
      lanelet::BasicPoint2d(p.x() - max_search_range, p.y() - max_search_range),
      lanelet::BasicPoint2d(p.x() + max_search_range, p.y() + max_search_range));
    // std::as_const(*ptr) to use the const version of the search function
    auto candidates = std::as_const(*lanelet_map_ptr_).laneletLayer.search(bbox);
    candidates.erase(
      std::remove_if(
        candidates.begin(), candidates.end(), [&](const auto & l) { return !isRoadLanelet(l); }),
      candidates.end());
    if (const auto closest_lanelet =
          experimental::lanelet2_utils::get_closest_lanelet(candidates, start_checkpoint);
        closest_lanelet) {
      start_lanelet = closest_lanelet.value();
      start_lanelets = {start_lanelet};
    }
  }
  if (start_lanelets.empty()) {
    RCLCPP_WARN_STREAM(
      logger_, "Failed to find current lanelet."
                 << std::endl
                 << " - start checkpoint: " << toString(start_checkpoint) << std::endl
                 << " - goal checkpoint: " << toString(goal_checkpoint) << std::endl);
    return false;
  }

  // Find lanelets for goal point.
  lanelet::ConstLanelet goal_lanelet;
  const lanelet::BasicPoint2d p(goal_checkpoint.position.x, goal_checkpoint.position.y);
  const lanelet::BoundingBox2d bbox(
    lanelet::BasicPoint2d(p.x() - max_search_range, p.y() - max_search_range),
    lanelet::BasicPoint2d(p.x() + max_search_range, p.y() + max_search_range));
  auto candidates = std::as_const(*lanelet_map_ptr_).laneletLayer.search(bbox);
  candidates.erase(
    std::remove_if(
      candidates.begin(), candidates.end(), [&](const auto & l) { return !isRoadLanelet(l); }),
    candidates.end());
  // if there is a lanelet in candidates that is included in previous preferred lanelets,
  // set it as goal_lanelet.
  // this is to select the same lane as much as possible when rerouting with waypoints.
  const auto findGoalClosestPreferredLanelet = [&]() -> std::optional<lanelet::ConstLanelet> {
    if (const auto closest_lanelet = getClosestPreferredLaneletWithinRoute(goal_checkpoint)) {
      if (std::find(candidates.begin(), candidates.end(), closest_lanelet) != candidates.end()) {
        if (autoware::experimental::lanelet2_utils::is_in_lanelet(
              goal_checkpoint, closest_lanelet.value())) {
          return closest_lanelet;
        }
      }
    }
    lanelet::ConstLanelet closest_lanelet;
    if (getClosestLaneletWithinRoute(goal_checkpoint, &closest_lanelet)) {
      if (std::find(candidates.begin(), candidates.end(), closest_lanelet) != candidates.end()) {
        if (autoware::experimental::lanelet2_utils::is_in_lanelet(
              goal_checkpoint, closest_lanelet)) {
          std::stringstream preferred_lanelets_str;
          for (const auto & preferred_lanelet : preferred_lanelets_) {
            preferred_lanelets_str << preferred_lanelet.id() << ", ";
          }
          RCLCPP_WARN(
            logger_,
            "Failed to find reroute on previous preferred lanelets %s, but on previous route "
            "segment %ld still",
            preferred_lanelets_str.str().c_str(), closest_lanelet.id());
          return closest_lanelet;
        }
      }
    }
    return std::nullopt;
  };
  if (auto closest_lanelet = findGoalClosestPreferredLanelet()) {
    goal_lanelet = closest_lanelet.value();
  } else {
    closest_lanelet =
      experimental::lanelet2_utils::get_closest_lanelet(candidates, goal_checkpoint);
    if (!closest_lanelet) {
      RCLCPP_WARN_STREAM(
        logger_, "Failed to find closest lanelet."
                   << std::endl
                   << " - start checkpoint: " << toString(start_checkpoint) << std::endl
                   << " - goal checkpoint: " << toString(goal_checkpoint) << std::endl);
      return false;
    }
    goal_lanelet = closest_lanelet.value();
  }

  lanelet::Optional<lanelet::routing::Route> optional_route;
  lanelet::routing::LaneletPath shortest_path;
  bool is_route_found = false;

  double min_route_cost = std::numeric_limits<double>::max();
  constexpr double yaw_threshold = M_PI / 2.0;
  constexpr double angle_diff_weight = 1000.0;

  for (const auto & st_llt : start_lanelets) {
    // check if the angle difference between start_checkpoint and start lanelet center line
    // orientation is in yaw_threshold range
    double lanelet_angle = autoware::experimental::lanelet2_utils::get_lanelet_angle(
      st_llt,
      autoware::experimental::lanelet2_utils::from_ros(start_checkpoint.position).basicPoint());
    double pose_yaw = tf2::getYaw(start_checkpoint.orientation);
    double angle_diff = std::abs(autoware_utils_math::normalize_radian(lanelet_angle - pose_yaw));

    bool is_proper_angle = angle_diff <= std::abs(yaw_threshold);

    optional_route = routing_graph_ptr_->getRoute(st_llt, goal_lanelet, 0);
    if (!optional_route || !is_proper_angle) {
      RCLCPP_DEBUG_STREAM(
        logger_, "Failed to find a proper route!"
                   << std::endl
                   << " - start checkpoint: " << toString(start_checkpoint) << std::endl
                   << " - goal checkpoint: " << toString(goal_checkpoint) << std::endl
                   << " - start lane id: " << st_llt.id() << std::endl
                   << " - goal lane id: " << goal_lanelet.id() << std::endl);
      continue;
    }
    is_route_found = true;
    if (const auto preferred_lane = getClosestPreferredLaneletWithinRoute(start_checkpoint)) {
      if (st_llt.id() == preferred_lane.value().id()) {
        shortest_path = optional_route->shortestPath();
        start_lanelet = st_llt;
        break;
      }
    }
    const double optional_route_length = optional_route->length2d();
    const double optional_route_cost = optional_route_length + angle_diff_weight * angle_diff;
    RCLCPP_DEBUG(
      logger_, "Lanelet ID %ld: Route length = %.1f, Angle Diff = %.4f rad, Route cost = %.2f",
      st_llt.id(), optional_route_length, angle_diff, optional_route_cost);
    if (optional_route_cost < min_route_cost) {
      min_route_cost = optional_route_cost;
      shortest_path = optional_route->shortestPath();
      start_lanelet = st_llt;
    }
  }

  if (is_route_found) {
    lanelet::routing::LaneletPath path;
    path = [&]() -> lanelet::routing::LaneletPath {
      if (consider_no_drivable_lanes && hasNoDrivableLaneInPath(shortest_path)) {
        const auto drivable_lane_path = findDrivableLanePath(start_lanelet, goal_lanelet);
        if (drivable_lane_path) return *drivable_lane_path;
      }
      return shortest_path;
    }();

    path_lanelets->reserve(path.size());
    for (const auto & llt : path) {
      path_lanelets->push_back(llt);
    }
  } else {
    RCLCPP_ERROR_STREAM(
      logger_, "Failed to find a proper route!"
                 << std::endl
                 << " - start checkpoint: " << toString(start_checkpoint) << std::endl
                 << " - goal checkpoint: " << toString(goal_checkpoint) << std::endl
                 << " - start lane ids: " << convertLaneletsIdToString(start_lanelets) << std::endl
                 << " - goal lane id: " << goal_lanelet.id() << std::endl);
  }

  return is_route_found;
}

lanelet::ConstLanelets RouteHandler::getRoadLaneletsAtPose(const Pose & pose) const
{
  lanelet::ConstLanelets road_lanelets_at_pose;
  const lanelet::BasicPoint2d p{pose.position.x, pose.position.y};
  const auto lanelets_at_pose = lanelet_map_ptr_->laneletLayer.search(lanelet::BoundingBox2d(p));
  for (const auto & lanelet_at_pose : lanelets_at_pose) {
    // confirm that the pose is inside the lanelet since "search" does an approximation with boxes
    const auto is_pose_inside_lanelet = lanelet::geometry::inside(lanelet_at_pose, p);
    if (is_pose_inside_lanelet && isRoadLanelet(lanelet_at_pose))
      road_lanelets_at_pose.push_back(lanelet_at_pose);
  }
  return road_lanelets_at_pose;
}

IfLL<LaneletT, bool> inside(const LaneletT& lanelet, const BasicPoint2d& point) {
  return boost::geometry::covered_by(point, lanelet.polygon2d());
}

bool RouteHandler::isRoadLanelet(const lanelet::ConstLanelet & lanelet) const
{
  return lanelet.hasAttribute(lanelet::AttributeName::Subtype) &&
         lanelet.attribute(lanelet::AttributeName::Subtype) == lanelet::AttributeValueString::Road;
}

const auto findGoalClosestPreferredLanelet = [&]() -> std::optional<lanelet::ConstLanelet> {
  if (const auto closest_lanelet = getClosestPreferredLaneletWithinRoute(goal_checkpoint)) {
    if (std::find(candidates.begin(), candidates.end(), closest_lanelet) != candidates.end()) {
      if (autoware::experimental::lanelet2_utils::is_in_lanelet(
            goal_checkpoint, closest_lanelet.value())) {
        return closest_lanelet;
      }
    }
  }
  lanelet::ConstLanelet closest_lanelet;
  if (getClosestLaneletWithinRoute(goal_checkpoint, &closest_lanelet)) {
    if (std::find(candidates.begin(), candidates.end(), closest_lanelet) != candidates.end()) {
      if (autoware::experimental::lanelet2_utils::is_in_lanelet(
            goal_checkpoint, closest_lanelet)) {
        std::stringstream preferred_lanelets_str;
        for (const auto & preferred_lanelet : preferred_lanelets_) {
          preferred_lanelets_str << preferred_lanelet.id() << ", ";
        }
        RCLCPP_WARN(
          logger_,
          "Failed to find reroute on previous preferred lanelets %s, but on previous route "
          "segment %ld still",
          preferred_lanelets_str.str().c_str(), closest_lanelet.id());
        return closest_lanelet;
      }
    }
  }
  return std::nullopt;
};

std::optional<lanelet::ConstLanelet> RouteHandler::getClosestPreferredLaneletWithinRoute(
  const Pose & search_pose) const
{
  return experimental::lanelet2_utils::get_closest_lanelet(preferred_lanelets_, search_pose);
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  lanelet::ConstLanelets candidate_lanelets;
  double min_distance = std::numeric_limits<double>::max();
  for (const auto & llt : lanelets) {
    /*
      NOTE(soblin):
      if point is on the edge of, or within the area of that polygon, distance is
      0.0.
      comparable_distance is a distance that maybe be x*x+y*y, not std::hypot of it,
      which is used to only compare distance
      stackoverflow.com/questions/51267577/boost-geometry-polygon-distance-for-inside-point
     */
    const double distance = boost::geometry::comparable_distance(
      llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    /*
      NOTE(soblin): this line is intended to push all lanelets on which search_point is located to
      candidate, and later judge by angle
     */
    if (std::fabs(distance - min_distance) <= std::numeric_limits<double>::epsilon()) {
      candidate_lanelets.push_back(llt);
    } else if (distance < min_distance) {
      candidate_lanelets.clear();
      candidate_lanelets.push_back(llt);
      min_distance = distance;
    }
  }

  if (candidate_lanelets.size() == 1) {
    return candidate_lanelets.front();
  }

  // find by angle
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet{};
  for (const auto & llt : candidate_lanelets) {
    const lanelet::ConstLineString3d segment = get_closest_segment(llt.centerline(), search_point);
    if (segment.empty()) {
      continue;
    }
    const auto segment_angle = std::atan2(
      segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
    const auto angle_diff =
      std::fabs(autoware_utils_math::normalize_radian(segment_angle - pose_yaw));
    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      closest_lanelet = llt;
    }
  }
  return closest_lanelet;
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Pose & src)
{
  return from_ros(src.position);
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Point & src)
{
  return lanelet::ConstPoint3d(lanelet::Point3d(lanelet::InvalId, src.x, src.y, src.z));
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

bool is_in_lanelet(
  const geometry_msgs::msg::Pose & pose, const lanelet::ConstLanelet & lanelet, const double radius)
{
  constexpr double epsilon = 1.0e-9;
  const double abs_radius = radius >= 0 ? radius : std::fabs(radius);
  if (radius < 0) {
    RCLCPP_WARN(
      rclcpp::get_logger("autoware_lanelet_utility"),
      "Input radius is negative, applying absolute.");
  }
  const lanelet::BasicPoint2d p(pose.position.x, pose.position.y);
  return boost::geometry::distance(p, lanelet.polygon2d().basicPolygon()) < abs_radius + epsilon;
}

bool RouteHandler::getClosestLaneletWithinRoute(
  const Pose & search_pose, lanelet::ConstLanelet * closest_lanelet) const
{
  if (route_lanelets_.empty() || closest_lanelet == nullptr) {
    return false;
  }
  const auto search_point = lanelet::BasicPoint2d(search_pose.position.x, search_pose.position.y);
  const auto query_nearest = boost::geometry::index::nearest(search_point, route_lanelets_.size());
  auto min_dist_to_route_lanelet = std::numeric_limits<double>::max();
  size_t nearest_id = 0;
  // search starting from the nearest bounding box
  for (auto query_it = route_lanelets_rtree_.qbegin(query_nearest);
       query_it != route_lanelets_rtree_.qend(); ++query_it) {
    const auto dist_to_bbox = boost::geometry::comparable_distance(search_point, query_it->first);
    // stop when the distance to the bounding box is larger than the min distance found so far
    if (dist_to_bbox > min_dist_to_route_lanelet) {
      break;
    }
    const auto dist = boost::geometry::comparable_distance(
      search_point, route_lanelets_[query_it->second].polygon2d().basicPolygon());
    if (dist < min_dist_to_route_lanelet) {
      min_dist_to_route_lanelet = dist;
      nearest_id = query_it->second;
    }
  }
  *closest_lanelet = route_lanelets_[nearest_id];
  return true;
}

std::optional<lanelet::ConstLanelet> RouteHandler::getClosestPreferredLaneletWithinRoute(
  const Pose & search_pose) const
{
  return experimental::lanelet2_utils::get_closest_lanelet(preferred_lanelets_, search_pose);
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  lanelet::ConstLanelets candidate_lanelets;
  double min_distance = std::numeric_limits<double>::max();
  for (const auto & llt : lanelets) {
    /*
      NOTE(soblin):
      if point is on the edge of, or within the area of that polygon, distance is
      0.0.
      comparable_distance is a distance that maybe be x*x+y*y, not std::hypot of it,
      which is used to only compare distance
      stackoverflow.com/questions/51267577/boost-geometry-polygon-distance-for-inside-point
     */
    const double distance = boost::geometry::comparable_distance(
      llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    /*
      NOTE(soblin): this line is intended to push all lanelets on which search_point is located to
      candidate, and later judge by angle
     */
    if (std::fabs(distance - min_distance) <= std::numeric_limits<double>::epsilon()) {
      candidate_lanelets.push_back(llt);
    } else if (distance < min_distance) {
      candidate_lanelets.clear();
      candidate_lanelets.push_back(llt);
      min_distance = distance;
    }
  }

  if (candidate_lanelets.size() == 1) {
    return candidate_lanelets.front();
  }

  // find by angle
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet{};
  for (const auto & llt : candidate_lanelets) {
    const lanelet::ConstLineString3d segment = get_closest_segment(llt.centerline(), search_point);
    if (segment.empty()) {
      continue;
    }
    const auto segment_angle = std::atan2(
      segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
    const auto angle_diff =
      std::fabs(autoware_utils_math::normalize_radian(segment_angle - pose_yaw));
    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      closest_lanelet = llt;
    }
  }
  return closest_lanelet;
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

std::optional<lanelet::routing::LaneletPath> RouteHandler::findDrivableLanePath(
  const lanelet::ConstLanelet & start_lanelet, const lanelet::ConstLanelet & goal_lanelet) const
{
  // we create a new routing graph with infinite cost on no drivable lanes
  const auto drivable_routing_graph_ptr = lanelet::routing::RoutingGraph::build(
    *lanelet_map_ptr_, *traffic_rules_ptr_,
    lanelet::routing::RoutingCostPtrs{std::make_shared<RoutingCostDrivable>()});
  const auto route = drivable_routing_graph_ptr->getRoute(start_lanelet, goal_lanelet, 0);
  if (route) return route->shortestPath();
  return {};
}

void RouteHandler::setRouteLanelets(const lanelet::ConstLanelets & path_lanelets)
{
  if (!path_lanelets.empty()) {
    const auto & first_lanelet = path_lanelets.front();
    start_lanelets_ = autoware::experimental::lanelet2_utils::all_neighbor_lanelets(
      first_lanelet, routing_graph_ptr_);
    const auto & last_lanelet = path_lanelets.back();
    goal_lanelets_ = autoware::experimental::lanelet2_utils::all_neighbor_lanelets(
      last_lanelet, routing_graph_ptr_);
  }

  // set route lanelets
  std::unordered_set<lanelet::Id> route_lanelets_id;
  std::unordered_set<lanelet::Id> candidate_lanes_id;
  for (const auto & lane : path_lanelets) {
    route_lanelets_id.insert(lane.id());
    const auto right_relations = routing_graph_ptr_->rightRelations(lane);
    for (const auto & right_relation : right_relations) {
      if (right_relation.relationType == lanelet::routing::RelationType::Right) {
        route_lanelets_id.insert(right_relation.lanelet.id());
      } else if (right_relation.relationType == lanelet::routing::RelationType::AdjacentRight) {
        candidate_lanes_id.insert(right_relation.lanelet.id());
      }
    }
    const auto left_relations = routing_graph_ptr_->leftRelations(lane);
    for (const auto & left_relation : left_relations) {
      if (left_relation.relationType == lanelet::routing::RelationType::Left) {
        route_lanelets_id.insert(left_relation.lanelet.id());
      } else if (left_relation.relationType == lanelet::routing::RelationType::AdjacentLeft) {
        candidate_lanes_id.insert(left_relation.lanelet.id());
      }
    }
  }

  //  check if candidates are really part of route
  for (const auto & candidate_id : candidate_lanes_id) {
    lanelet::ConstLanelet lanelet = lanelet_map_ptr_->laneletLayer.get(candidate_id);
    auto previous_lanelets = routing_graph_ptr_->previous(lanelet);
    bool is_connected_to_main_lanes_prev = false;
    bool is_connected_to_candidate_prev = true;
    if (exists(start_lanelets_, lanelet)) {
      is_connected_to_candidate_prev = false;
    }
    while (!previous_lanelets.empty() && is_connected_to_candidate_prev &&
           !is_connected_to_main_lanes_prev) {
      is_connected_to_candidate_prev = false;

      for (const auto & prev_lanelet : previous_lanelets) {
        if (route_lanelets_id.find(prev_lanelet.id()) != route_lanelets_id.end()) {
          is_connected_to_main_lanes_prev = true;
          break;
        }
        if (exists(start_lanelets_, prev_lanelet)) {
          break;
        }

        if (candidate_lanes_id.find(prev_lanelet.id()) != candidate_lanes_id.end()) {
          is_connected_to_candidate_prev = true;
          previous_lanelets = routing_graph_ptr_->previous(prev_lanelet);
          break;
        }
      }
    }

    auto following_lanelets = routing_graph_ptr_->following(lanelet);
    bool is_connected_to_main_lanes_next = false;
    bool is_connected_to_candidate_next = true;
    if (exists(goal_lanelets_, lanelet)) {
      is_connected_to_candidate_next = false;
    }
    while (!following_lanelets.empty() && is_connected_to_candidate_next &&
           !is_connected_to_main_lanes_next) {
      is_connected_to_candidate_next = false;
      for (const auto & next_lanelet : following_lanelets) {
        if (route_lanelets_id.find(next_lanelet.id()) != route_lanelets_id.end()) {
          is_connected_to_main_lanes_next = true;
          break;
        }
        if (exists(goal_lanelets_, next_lanelet)) {
          break;
        }
        if (candidate_lanes_id.find(next_lanelet.id()) != candidate_lanes_id.end()) {
          is_connected_to_candidate_next = true;
          following_lanelets = routing_graph_ptr_->following(next_lanelet);
          break;
        }
      }
    }

    if (is_connected_to_main_lanes_next && is_connected_to_main_lanes_prev) {
      route_lanelets_id.insert(candidate_id);
    }
  }

  route_lanelets_.clear();
  route_lanelets_.reserve(route_lanelets_id.size());
  std::vector<RouteRtreeNode> rtree_nodes;
  rtree_nodes.reserve(route_lanelets_id.size());
  size_t i = 0;
  for (const auto & id : route_lanelets_id) {
    route_lanelets_.push_back(lanelet_map_ptr_->laneletLayer.get(id));
    rtree_nodes.emplace_back(
      boost::geometry::return_envelope<autoware_utils_geometry::Box2d>(
        route_lanelets_.back().polygon2d().basicPolygon()),
      i++);
  }
  route_lanelets_rtree_ = RouteRtree(rtree_nodes);
  is_handler_ready_ = true;
}

lanelet::ConstLanelets all_neighbor_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;

  auto left_opt = left_lanelets(lanelet, routing_graph);
  auto right_opt = right_lanelets(lanelet, routing_graph);

  if (!left_opt.has_value() && !right_opt.has_value()) {
    lanelets.push_back(lanelet);
    return lanelets;
  }

  if (left_opt.has_value()) {
    auto left_lls = left_opt.value();
    std::reverse(left_lls.begin(), left_lls.end());
    lanelets.insert(lanelets.end(), left_lls.begin(), left_lls.end());
  }

  lanelets.push_back(lanelet);

  if (right_opt.has_value()) {
    auto right_lls = right_opt.value();
    lanelets.insert(lanelets.end(), right_lls.begin(), right_lls.end());
  }

  return lanelets;
}

std::optional<lanelet::ConstLanelets> left_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;
  auto left_lane = left_lanelet(lanelet, routing_graph);
  // If the left lane doesn't exist at the first place.
  if (!left_lane.has_value()) {
    return std::nullopt;
  }
  // If the left lane exists.
  while (left_lane.has_value()) {
    lanelets.push_back(left_lane.value());
    left_lane = left_lanelet(left_lane.value(), routing_graph);
  }
  return lanelets;
}

std::optional<lanelet::ConstLanelet> left_lanelet(
  const lanelet::ConstLanelet & lanelet, const lanelet::routing::RoutingGraphConstPtr routing_graph)
{
  if (const auto left_lane = routing_graph->left(lanelet)) {
    // lane changeable
    return *left_lane;
  }
  if (const auto adjacent_left_lane = routing_graph->adjacentLeft(lanelet)) {
    return *adjacent_left_lane;
  }
  return std::nullopt;
}

std::optional<lanelet::ConstLanelets> right_lanelets(
  const lanelet::ConstLanelet & lanelet,
  const lanelet::routing::RoutingGraphConstPtr & routing_graph)
{
  lanelet::ConstLanelets lanelets;
  auto right_lane = right_lanelet(lanelet, routing_graph);
  // If the right lane doesn't exist at the first place.
  if (!right_lane.has_value()) {
    return std::nullopt;
  }
  // If the right lane exists.
  while (right_lane.has_value()) {
    lanelets.push_back(right_lane.value());
    right_lane = right_lanelet(right_lane.value(), routing_graph);
  }
  return lanelets;
}

std::optional<lanelet::ConstLanelet> right_lanelet(
  const lanelet::ConstLanelet & lanelet, const lanelet::routing::RoutingGraphConstPtr routing_graph)
{
  if (const auto right_lane = routing_graph->right(lanelet)) {
    // lane changeable
    return *right_lane;
  }
  if (const auto adjacent_right_lane = routing_graph->adjacentRight(lanelet)) {
    return *adjacent_right_lane;
  }
  return std::nullopt;
}

geometry_msgs::msg::Pose get_closest_centerline_pose(
  const lanelet::ConstLanelets & road_lanelets, const geometry_msgs::msg::Pose & point,
  autoware::vehicle_info_utils::VehicleInfo vehicle_info)
{
  auto opt = autoware::experimental::lanelet2_utils::get_closest_lanelet_within_constraint(
    road_lanelets, point, 0.0);
  if (!opt.has_value()) {
    // point is not on any lanelet.
    return point;
  }
  lanelet::Lanelet closest_lanelet = autoware::experimental::lanelet2_utils::remove_const(*opt);

  const auto refined_center_line =
    autoware::experimental::lanelet2_utils::get_fine_centerline(closest_lanelet, 1.0);
  closest_lanelet.setCenterline(
    autoware::experimental::lanelet2_utils::remove_const(refined_center_line));

  const double lane_yaw = autoware::experimental::lanelet2_utils::get_lanelet_angle(
    closest_lanelet, autoware::experimental::lanelet2_utils::from_ros(point.position).basicPoint());

  const auto nearest_idx = autoware::motion_utils::findNearestIndex(
    convertCenterlineToPoints(closest_lanelet), point.position);
  const auto nearest_point = closest_lanelet.centerline()[nearest_idx];

  // shift nearest point on its local y axis so that vehicle's right and left edges
  // would have approx the same clearance from road border
  const auto shift_length = (vehicle_info.right_overhang_m - vehicle_info.left_overhang_m) / 2.0;
  const auto delta_x = -shift_length * std::sin(lane_yaw);
  const auto delta_y = shift_length * std::cos(lane_yaw);

  lanelet::BasicPoint3d refined_point(
    nearest_point.x() + delta_x, nearest_point.y() + delta_y, nearest_point.z());

  return convertBasicPoint3dToPose(refined_point, lane_yaw);
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet_within_constraint(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose,
  const double dist_threshold, const double yaw_threshold)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  std::vector<std::pair<lanelet::ConstLanelet, double>> candidate_lanelets;
  for (const auto & llt : lanelets) {
    const double distance =
      boost::geometry::distance(llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    if (distance <= dist_threshold) {
      candidate_lanelets.emplace_back(llt, distance);
    }
  }

  if (candidate_lanelets.empty()) {
    return std::nullopt;
  }

  // sort by distance
  std::sort(
    candidate_lanelets.begin(), candidate_lanelets.end(),
    [](
      const std::pair<lanelet::ConstLanelet, double> & x,
      const std::pair<lanelet::ConstLanelet, double> & y) { return x.second < y.second; });

  // find closest lanelet within yaw_threshold
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  double min_distance = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet;
  for (const auto & llt_pair : candidate_lanelets) {
    const auto & distance = llt_pair.second;

    double lanelet_angle = get_lanelet_angle(llt_pair.first, search_point);
    double angle_diff = std::fabs(autoware_utils_math::normalize_radian(lanelet_angle - pose_yaw));
    // reject
    if (angle_diff > std::fabs(yaw_threshold)) continue;

    // only 1st item
    if (min_distance < distance) break;

    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      min_distance = distance;
      closest_lanelet = llt_pair.first;
    }
  }

  return closest_lanelet;
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Pose & src)
{
  return from_ros(src.position);
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Point & src)
{
  return lanelet::ConstPoint3d(lanelet::Point3d(lanelet::InvalId, src.x, src.y, src.z));
}

double get_lanelet_angle(
  const lanelet::ConstLanelet & lanelet, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d segment = get_closest_segment(lanelet.centerline(), search_pt);
  return std::atan2(
    segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

lanelet::ConstLineString3d get_fine_centerline(
  const lanelet::ConstLanelet & lanelet_obj, const double resolution)
{
  // get number of segments from resolution and longer bound
  const auto num_segments = compute_num_segments(lanelet_obj, resolution);

  // Resample points
  const auto left_points = resample_points(lanelet_obj.leftBound().basicLineString(), num_segments);
  const auto right_points =
    resample_points(lanelet_obj.rightBound().basicLineString(), num_segments);

  lanelet::ConstPoints3d center_points;
  for (size_t i = 0; i < num_segments + 1; i++) {
    const auto center_basic_point = (right_points.at(i) + left_points.at(i)) / 2;

    const lanelet::ConstPoint3d center_point(
      lanelet::InvalId, center_basic_point.x(), center_basic_point.y(), center_basic_point.z());
    center_points.push_back(center_point);
  }

  const auto centerline_opt = create_safe_linestring(center_points);
  if (!centerline_opt.has_value()) {
    RCLCPP_ERROR(
      rclcpp::get_logger("autoware_lanelet2_utility"),
      "center_points has less than two points. Returning empty linestring.");
    return lanelet::ConstLineString3d();
  }

  return *centerline_opt;
}

size_t compute_num_segments(const lanelet::ConstLanelet & lanelet, const double resolution)
{
  // Get length of longer border
  const double left_length = static_cast<double>(lanelet::geometry::length(lanelet.leftBound()));
  const double right_length = static_cast<double>(lanelet::geometry::length(lanelet.rightBound()));
  const double longer_distance = (left_length > right_length) ? left_length : right_length;
  const size_t num_segments = std::max(static_cast<int>(ceil(longer_distance / resolution)), 1);
  return num_segments;
}

lanelet::BasicPoints3d resample_points(
  const lanelet::BasicLineString3d & line_string, const size_t num_segments)
{
  // Note: this function works well with num_segments >= num_segment of line string
  // less than this, it might cause loss in information (such as corner curve)
  if (line_string.size() < 2 || num_segments == 0) {
    return {};
  }

  // Compute accumulated arc length
  std::vector<double> accumulated_lengths{0.0};
  accumulated_lengths.reserve(line_string.size());
  for (size_t i = 1; i < line_string.size(); ++i) {
    const double distance = lanelet::geometry::distance(line_string[i], line_string[i - 1]);
    accumulated_lengths.push_back(accumulated_lengths.back() + distance);
  }

  const double total_length = accumulated_lengths.back();

  lanelet::BasicPoints3d resampled_points;
  for (size_t i = 0; i <= num_segments; ++i) {
    const double target_length =
      total_length * static_cast<double>(i) / static_cast<double>(num_segments);

    // Find two nearest points
    // (accumulated_lengths[idx-1] < target_length <= accumulated_lengths[idx])
    auto it =
      std::lower_bound(accumulated_lengths.begin(), accumulated_lengths.end(), target_length);
    size_t idx = std::distance(accumulated_lengths.begin(), it);

    if (idx == 0) {
      resampled_points.push_back(line_string.front());
      continue;
    } else if (idx >= accumulated_lengths.size()) {
      resampled_points.push_back(line_string.back());
      break;
    }

    const double back_length = accumulated_lengths[idx - 1];
    const double front_length = accumulated_lengths[idx];
    const double ratio = (target_length - back_length) / (front_length - back_length);

    const lanelet::BasicPoint3d back_point = line_string[idx - 1];
    const lanelet::BasicPoint3d front_point = line_string[idx];

    const lanelet::BasicPoint3d direction_vector = front_point - back_point;
    const lanelet::BasicPoint3d target_point = back_point + direction_vector * ratio;

    resampled_points.push_back(target_point);
  }
  return resampled_points;
}

std::optional<lanelet::ConstLineString3d> create_safe_linestring(
  const std::vector<lanelet::ConstPoint3d> & points)
{
  if (points.size() < 2) {
    return std::nullopt;
  }
  std::vector<lanelet::Point3d> without_const_points;
  std::for_each(points.begin(), points.end(), [&](const auto & point) {
    without_const_points.push_back(remove_const(point));
  });
  lanelet::ConstLineString3d const_linestring(lanelet::InvalId, without_const_points);

  return const_linestring;
}

lanelet::LineString3d remove_const(const lanelet::ConstLineString3d & const_linestring)
{
  return lanelet::LineString3d{
    std::const_pointer_cast<lanelet::LineStringData>(const_linestring.constData())};
}

double get_lanelet_angle(
  const lanelet::ConstLanelet & lanelet, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d segment = get_closest_segment(lanelet.centerline(), search_pt);
  return std::atan2(
    segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Pose convertBasicPoint3dToPose(
  const lanelet::BasicPoint3d & point, const double lane_yaw)
{
  // calculate new orientation of goal
  geometry_msgs::msg::Pose pose;
  pose.position.x = point.x();
  pose.position.y = point.y();
  pose.position.z = point.z();

  pose.orientation = autoware_utils::create_quaternion_from_yaw(lane_yaw);

  return pose;
}

geometry_msgs::msg::Quaternion create_quaternion_from_yaw(const double yaw)
{
  tf2::Quaternion q;
  q.setRPY(0, 0, yaw);
  return tf2::toMsg(q);
}

bool DefaultPlanner::is_goal_valid(const geometry_msgs::msg::Pose & goal)
{
  const auto logger = node_->get_logger();

  const auto goal_lanelet_pt = experimental::lanelet2_utils::from_ros(goal.position);

  // check if goal is in shoulder lanelet
  const auto shoulder_lanelets = route_handler_.getShoulderLaneletsAtPose(goal);
  if (const auto closest_shoulder_lanelet_opt =
        experimental::lanelet2_utils::get_closest_lanelet_within_constraint(
          shoulder_lanelets, goal);
      closest_shoulder_lanelet_opt) {
    const auto & closest_shoulder_lanelet = closest_shoulder_lanelet_opt.value();
    const auto lane_yaw = autoware::experimental::lanelet2_utils::get_lanelet_angle(
      closest_shoulder_lanelet,
      autoware::experimental::lanelet2_utils::from_ros(goal.position).basicPoint());
    const auto goal_yaw = tf2::getYaw(goal.orientation);
    const auto angle_diff = autoware_utils::normalize_radian(lane_yaw - goal_yaw);
    const double th_angle = autoware_utils::deg2rad(param_.goal_angle_threshold_deg);
    if (std::abs(angle_diff) < th_angle) {
      return true;
    }
  }
  const auto road_lanelets_at_goal = route_handler_.getRoadLaneletsAtPose(goal);
  auto closest_lanelet_to_goal_opt =
    experimental::lanelet2_utils::get_closest_lanelet(road_lanelets_at_goal, goal);
  if (!closest_lanelet_to_goal_opt) {
    // if no road lanelets directly at the goal, find the closest one
    const lanelet::BasicPoint2d goal_point{goal.position.x, goal.position.y};
    auto closest_dist = std::numeric_limits<double>::max();
    const auto closest_road_lanelet_found =
      route_handler_.getLaneletMapPtr()->laneletLayer.nearestUntil(
        goal_point, [&](const auto & bbox, const auto & ll) {
          // this search is done by increasing distance between the bounding box and the goal
          // we stop the search when the bounding box is further than the closest dist found
          if (lanelet::geometry::distance2d(bbox, goal_point) > closest_dist)
            return true;  // stop the search
          const auto dist = lanelet::geometry::distance2d(goal_point, ll.polygon2d());
          if (route_handler_.isRoadLanelet(ll) && dist < closest_dist) {
            closest_dist = dist;
            closest_lanelet_to_goal_opt = ll;
          }
          return false;  // continue the search
        });
    if (!closest_road_lanelet_found) return false;
  }

  // If the goal is at the very beginning or the end of closest_lanelet_to_goal, base link to rear
  // part of ego footprint will be outside of it. To tolerate it, add previous and next lanelets
  const auto & closest_lanelet_to_goal = closest_lanelet_to_goal_opt.value();
  lanelet::ConstLanelets lanelets_near_goal{closest_lanelet_to_goal};
  const auto previous_lanelets = get_lanelets_to(
    closest_lanelet_to_goal, vehicle_info_.max_longitudinal_offset_m, true, route_handler_);
  lanelets_near_goal.insert(
    lanelets_near_goal.begin(), previous_lanelets.begin(), previous_lanelets.end());
  const auto next_lanelets = get_lanelets_to(
    closest_lanelet_to_goal, vehicle_info_.max_longitudinal_offset_m, false, route_handler_);
  lanelets_near_goal.insert(lanelets_near_goal.end(), next_lanelets.begin(), next_lanelets.end());

  const auto local_vehicle_footprint = vehicle_info_.createFootprint();
  autoware_utils::LinearRing2d goal_footprint =
    autoware_utils::transform_vector(local_vehicle_footprint, autoware_utils::pose2transform(goal));
  pub_goal_footprint_marker_->publish(visualize_debug_footprint(goal_footprint));
  const auto polygon_footprint = convert_linear_ring_to_polygon(goal_footprint);

  // check if goal footprint exceeds lane when the goal isn't in parking_lot
  if (
    param_.check_footprint_inside_lanes &&
    !check_goal_footprint_inside_lanes(lanelets_near_goal, polygon_footprint) &&
    !is_in_parking_lot(
      lanelet::utils::query::getAllParkingLots(route_handler_.getLaneletMapPtr()),
      experimental::lanelet2_utils::from_ros(goal.position))) {
    RCLCPP_WARN(logger, "Goal's footprint exceeds lane!");
    return false;
  }

  if (is_in_lane(closest_lanelet_to_goal, goal_lanelet_pt)) {
    const auto lane_yaw = autoware::experimental::lanelet2_utils::get_lanelet_angle(
      closest_lanelet_to_goal,
      autoware::experimental::lanelet2_utils::from_ros(goal.position).basicPoint());
    const auto goal_yaw = tf2::getYaw(goal.orientation);
    const auto angle_diff = autoware_utils::normalize_radian(lane_yaw - goal_yaw);

    const double th_angle = autoware_utils::deg2rad(param_.goal_angle_threshold_deg);
    if (std::abs(angle_diff) < th_angle) {
      return true;
    }
  }

  // check if goal is in parking space
  const auto parking_spaces =
    lanelet::utils::query::getAllParkingSpaces(route_handler_.getLaneletMapPtr());
  if (is_in_parking_space(parking_spaces, goal_lanelet_pt)) {
    return true;
  }

  // check if goal is in parking lot
  const auto parking_lots =
    lanelet::utils::query::getAllParkingLots(route_handler_.getLaneletMapPtr());
  return is_in_parking_lot(parking_lots, goal_lanelet_pt);
}

lanelet::ConstLanelets RouteHandler::getShoulderLaneletsAtPose(const Pose & pose) const
{
  lanelet::ConstLanelets lanelets_at_pose;
  const lanelet::BasicPoint2d p{pose.position.x, pose.position.y};
  const auto candidates_at_pose = lanelet_map_ptr_->laneletLayer.search(lanelet::BoundingBox2d(p));
  for (const auto & candidate : candidates_at_pose) {
    // confirm that the pose is inside the lanelet since "search" does an approximation with boxes
    const auto is_pose_inside_lanelet = lanelet::geometry::inside(candidate, p);
    if (is_pose_inside_lanelet && isShoulderLanelet(candidate))
      lanelets_at_pose.push_back(candidate);
  }
  return lanelets_at_pose;
}

IfLL<LaneletT, bool> inside(const LaneletT& lanelet, const BasicPoint2d& point) {
  return boost::geometry::covered_by(point, lanelet.polygon2d());
}

bool RouteHandler::isShoulderLanelet(const lanelet::ConstLanelet & lanelet) const
{
  return lanelet.hasAttribute(lanelet::AttributeName::Subtype) &&
         lanelet.attribute(lanelet::AttributeName::Subtype) == "road_shoulder";
}

std::optional<lanelet::ConstLanelet> get_closest_lanelet(
  const lanelet::ConstLanelets & lanelets, const geometry_msgs::msg::Pose & search_pose)
{
  if (lanelets.empty()) {
    return std::nullopt;
  }

  const lanelet::BasicPoint3d search_point = from_ros(search_pose);

  lanelet::ConstLanelets candidate_lanelets;
  double min_distance = std::numeric_limits<double>::max();
  for (const auto & llt : lanelets) {
    /*
      NOTE(soblin):
      if point is on the edge of, or within the area of that polygon, distance is
      0.0.
      comparable_distance is a distance that maybe be x*x+y*y, not std::hypot of it,
      which is used to only compare distance
      stackoverflow.com/questions/51267577/boost-geometry-polygon-distance-for-inside-point
     */
    const double distance = boost::geometry::comparable_distance(
      llt.polygon2d().basicPolygon(), lanelet::utils::to2D(search_point));

    /*
      NOTE(soblin): this line is intended to push all lanelets on which search_point is located to
      candidate, and later judge by angle
     */
    if (std::fabs(distance - min_distance) <= std::numeric_limits<double>::epsilon()) {
      candidate_lanelets.push_back(llt);
    } else if (distance < min_distance) {
      candidate_lanelets.clear();
      candidate_lanelets.push_back(llt);
      min_distance = distance;
    }
  }

  if (candidate_lanelets.size() == 1) {
    return candidate_lanelets.front();
  }

  // find by angle
  const double pose_yaw = tf2::getYaw(search_pose.orientation);
  double min_angle = std::numeric_limits<double>::max();
  std::optional<lanelet::ConstLanelet> closest_lanelet{};
  for (const auto & llt : candidate_lanelets) {
    const lanelet::ConstLineString3d segment = get_closest_segment(llt.centerline(), search_point);
    if (segment.empty()) {
      continue;
    }
    const auto segment_angle = std::atan2(
      segment.back().y() - segment.front().y(), segment.back().x() - segment.front().x());
    const auto angle_diff =
      std::fabs(autoware_utils_math::normalize_radian(segment_angle - pose_yaw));
    if (angle_diff < min_angle) {
      min_angle = angle_diff;
      closest_lanelet = llt;
    }
  }
  return closest_lanelet;
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Pose & src)
{
  return from_ros(src.position);
}

lanelet::ConstPoint3d from_ros(const geometry_msgs::msg::Point & src)
{
  return lanelet::ConstPoint3d(lanelet::Point3d(lanelet::InvalId, src.x, src.y, src.z));
}

lanelet::ConstLineString3d get_closest_segment(
  const lanelet::ConstLineString3d & linestring, const lanelet::BasicPoint3d & search_pt)
{
  lanelet::ConstLineString3d closest_segment;
  double min_distance = std::numeric_limits<double>::max();

  for (const auto & [prev_pt, current_pt] :
       ranges::views::zip(linestring, linestring | ranges::views::drop(1))) {
    lanelet::Point3d prev_pt_3d(lanelet::InvalId, prev_pt.x(), prev_pt.y(), prev_pt.z());
    lanelet::Point3d current_pt_3d(
      lanelet::InvalId, current_pt.x(), current_pt.y(), current_pt.z());

    lanelet::ConstLineString3d current_segment(lanelet::InvalId, {prev_pt_3d, current_pt_3d});
    double distance = lanelet::geometry::distance3d(current_segment.basicLineString(), search_pt);
    if (distance < min_distance) {
      closest_segment = current_segment;
      min_distance = distance;
    }
  }
  return closest_segment;
}

inline double normalize_radian(const double rad, const double min_rad = -pi)
{
  const auto max_rad = min_rad + 2 * pi;

  const auto value = std::fmod(rad, 2 * pi);
  if (min_rad <= value && value < max_rad) {
    return value;
  }

  return value - std::copysign(2 * pi, value);
}

bool DefaultPlanner::check_goal_footprint_inside_lanes(
  const lanelet::ConstLanelets & lanelets_near_goal,
  const autoware_utils::Polygon2d & goal_footprint) const
{
  lanelet::Points3d left_bound_points;
  lanelet::Points3d right_bound_points;

  for (const auto & lanelet : lanelets_near_goal) {
    if (const auto left_shoulder = route_handler_.getLeftShoulderLanelet(lanelet)) {
      for (const auto & point : left_shoulder->leftBound()) {
        left_bound_points.push_back(lanelet::Point3d(point));
      }
    } else {
      for (const auto & point : lanelet.leftBound()) {
        left_bound_points.push_back(lanelet::Point3d(point));
      }
    }

    if (const auto right_shoulder = route_handler_.getRightShoulderLanelet(lanelet)) {
      for (const auto & point : right_shoulder->rightBound()) {
        right_bound_points.push_back(lanelet::Point3d(point));
      }
    } else {
      for (const auto & point : lanelet.rightBound()) {
        right_bound_points.push_back(lanelet::Point3d(point));
      }
    }
  }

  auto lane_polygon =
    lanelet::Lanelet(
      lanelet::InvalId, lanelet::LineString3d(lanelet::InvalId, left_bound_points),
      lanelet::LineString3d(lanelet::InvalId, right_bound_points))
      .polygon2d()
      .basicPolygon();
  boost::geometry::correct(lane_polygon);

  return boost::geometry::covered_by(goal_footprint, lane_polygon);
}

std::optional<lanelet::ConstLanelet> RouteHandler::getLeftShoulderLanelet(
  const lanelet::ConstLanelet & lanelet) const
{
  for (const auto & other_lanelet :
       lanelet_map_ptr_->laneletLayer.findUsages(lanelet.leftBound())) {
    if (other_lanelet.rightBound() == lanelet.leftBound() && isShoulderLanelet(other_lanelet))
      return other_lanelet;
  }
  return std::nullopt;
}

std::vector<PrimitiveT> findUsages(const traits::ConstPrimitiveType<traits::OwnedT<PrimitiveT>>& primitive);

